"""Packing slip generation."""

from __future__ import annotations

from dataclasses import dataclass

from orders.application.errors import Conflict, OrderNotFound, ProductNotFound
from orders.infrastructure.catalog import InMemoryProductCatalog
from orders.infrastructure.customers import InMemoryCustomerRepository
from orders.infrastructure.repository import InMemoryOrderRepository
from orders.infrastructure.stock import InMemoryStockRepository


@dataclass(frozen=True)
class PackingSlipLine:
    sku: str
    name: str
    quantity: int


@dataclass(frozen=True)
class PackingSlip:
    order_id: str
    customer_name: str
    lines: tuple[PackingSlipLine, ...]


class FulfilmentService:
    def __init__(self, orders: InMemoryOrderRepository, customers: InMemoryCustomerRepository,
                 catalog: InMemoryProductCatalog, stock: InMemoryStockRepository) -> None:
        self._orders = orders
        self._customers = customers
        self._catalog = catalog
        self._stock = stock

    def get_packing_slip(self, order_id: str) -> PackingSlip:
        order = self._orders.get(order_id)
        if order is None:
            raise OrderNotFound(order_id)
        if order.status == "cancelled":
            raise Conflict(f"order {order_id} is cancelled")

        customer = self._customers.get(order.customer_id)
        customer_name = customer.name if customer is not None else ""

        lines = []
        for item in order.items:
            product = self._catalog.get(item.sku)
            product_name = product.name if product is not None else ""
            lines.append(PackingSlipLine(item.sku, product_name, item.quantity))

        return PackingSlip(order.order_id, customer_name, tuple(lines))

    def get_low_stock_products(self, threshold: int) -> list[tuple[str, str, int]]:
        low_stock = []
        stock_levels = self._stock.all_levels()
        for product in self._catalog.list_all():
            if product.active and stock_levels.get(product.sku, 0) < threshold:
                low_stock.append((product.sku, product.name, stock_levels.get(product.sku, 0)))
        low_stock.sort(key=lambda x: (x[2], x[0]))
        return low_stock

    def restock(self, sku: str, quantity: int) -> int:
        product = self._catalog.get(sku)
        if product is None:
            raise ProductNotFound(sku)
        current_stock = self._stock.get(sku)
        new_stock = current_stock + quantity
        self._stock.set(sku, new_stock)
        return new_stock

    def get_fulfilment_summary(self) -> tuple[int, int, int]:
        open_orders = 0
        units_to_pick = 0
        stock_levels = self._stock.all_levels()

        for order in self._orders.list_all():
            if order.status != "cancelled":
                open_orders += 1
                for item in order.items:
                    units_to_pick += item.quantity

        low_stock_products = 0
        for product in self._catalog.list_all():
            if product.active and stock_levels.get(product.sku, 0) < 5:
                low_stock_products += 1

        return open_orders, units_to_pick, low_stock_products

